<?php require __DIR__ . '/footer.php'; require __DIR__ . '/connect.php';
$errors=[];$name=trim($_POST['full_name']??'');$email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL);$sid=strtoupper(trim($_POST['student_id']??''));$msg=trim($_POST['message']??'');$topic=trim($_POST['topic']??'');$mode=trim($_POST['mode']??'');$skills=implode(', ',array_map('trim',$_POST['skills']??[]));
if($name==='')$errors[]='Name required'; if(!$email)$errors[]='A.06 invalid email'; if(!preg_match('/^DC[0-9]{6}$/',$sid))$errors[]='Invalid student ID'; if(strlen($msg)<10)$errors[]='Textarea too short'; if($topic==='')$errors[]='Topic required'; if($mode==='')$errors[]='Mode required';
if(!$errors){$stmt=$mysqli->prepare('INSERT INTO scenario_a_submissions(full_name,email,student_id,message,topic,study_mode,skills) VALUES(?,?,?,?,?,?,?)');$stmt->bind_param('sssssss',$name,$email,$sid,$msg,$topic,$mode,$skills);$ok=$stmt->execute();if(!$ok)$errors[]=$stmt->error;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A Result</title><link rel="stylesheet" href="../css/styles.css"></head><body><header><h1>A.05-A.10 PHP Result</h1><nav><a href="../index.php">Back</a><a class="secondary" href="list.php">Records</a></nav></header><main><section class="card"><?php if($errors):?><div class="notice error"><?=htmlspecialchars(implode('; ',$errors))?></div><?php else:?><div class="notice success">Saved by prepared statement. SQL injection avoided by bind_param().</div><table><tr><th>Name</th><td><?=htmlspecialchars($name)?></td></tr><tr><th>Email</th><td><?=htmlspecialchars($email)?></td></tr><tr><th>Message</th><td><?=nl2br(htmlspecialchars($msg))?></td></tr></table><?php endif;?></section></main><?php exam_footer(); ?></body></html>
